// Maintenance scenario service: change a backend health monitor, preview the predicted effect, deploy to the simulator, read
// the observed pool, and restore a known-good revision.
//
// The decision rules live in monitor-model.mjs and the observations come from maintenance-fixtures.mjs. This file only
// holds state and enforces the workflow:
//   - a lab owns its revisions and its plans; another lab's plan id answers like an unknown one,
//   - a plan is generated by the server from a base revision and a fixture digest, and expires,
//   - a deploy re-checks that the base revision and the fixtures are still what the plan saw, and executes at most once,
//   - history is never rewritten: restoring a revision plans a NEW revision from the old monitor.
// State is in memory and per lab. There are no timers, clocks beyond the injected one, or network calls.

import { randomBytes } from "node:crypto";
import { createHash } from "node:crypto";
import { can } from "../roles.mjs";
import { answerFor, FIXTURES, fixturesDigest } from "./maintenance-fixtures.mjs";
import { compare, evaluatePool, validateMonitor } from "./monitor-model.mjs";

const deny = (code, extra = {}) => ({ ok: false, code, ...extra });
const hash = (v) => createHash("sha256").update(JSON.stringify(v)).digest("hex");
const PLAN = /^PLN-[0-9A-F]{10}$/;

export function createMaintenance({ fixtures = FIXTURES, access, audit, now = () => new Date(), killSwitch = () => false, planTtlMs = 30 * 60_000 }) {
  const labs = new Map();
  const plans = new Map();
  const inflight = new Map();
  const member = (user) => typeof user?.labId === "string" && access?.member?.({ principalId: user.subject, contextId: user.labId }) === true;
  const evaluate = (monitor) => evaluatePool(monitor, fixtures.members, answerFor);

  const lab = (labId) => {
    if (!labs.has(labId)) {
      const monitor = { ...fixtures.knownGood };
      const pool = evaluate(monitor);
      labs.set(labId, { revisions: [{ rev: 1, monitor, source: "initial", poolState: pool.state, by: "system", at: now().toISOString() }], current: 1 });
    }
    return labs.get(labId);
  };
  const currentOf = (L) => L.revisions.find((r) => r.rev === L.current);

  const view = (user) => {
    const L = lab(user.labId);
    const cur = currentOf(L);
    const observed = evaluate(cur.monitor);
    const knownGood = [...L.revisions].reverse().find((r) => r.poolState === "available");
    return {
      // Desired (what was deployed) and observed (what the fixtures show under it) are separate.
      desired: { revision: cur.rev, monitor: cur.monitor },
      observed,
      knownGoodRevision: knownGood?.rev ?? null,
      revisions: L.revisions.map((r) => ({ rev: r.rev, monitor: r.monitor, source: r.source, restoreOf: r.restoreOf ?? null, poolState: r.poolState, by: r.by, at: r.at })),
      fixtures: { version: fixtures.version, digest: fixturesDigest(fixtures), memberBuilds: fixtures.members.map((m) => ({ id: m.id, build: m.build })) }
    };
  };

  const planView = (p) => ({ id: p.id, kind: p.kind, restoreOf: p.restoreOf, baseRevision: p.baseRevision, expiresAt: p.expiresAt, status: p.status, desired: { monitor: p.monitor }, predicted: p.predicted, change: p.change, fixturesDigest: p.fixturesDigest, result: p.result ?? null });
  const visible = (user, p) => member(user) && p.contextId === user.labId;

  return {
    get(user) { return member(user) ? view(user) : null; },

    /** Builds a server-generated plan from either a new monitor or a revision to restore. Writes nothing. */
    async plan(user, body) {
      if (!member(user)) return deny("forbidden");
      if (!can(user.roles, "scenario:run")) return deny("forbidden");
      if (killSwitch()) return deny("kill_switch_engaged");
      const L = lab(user.labId);
      let monitor; let kind = "change"; let restoreOf = null;
      if (body?.restoreRevision !== undefined) {
        const target = L.revisions.find((r) => r.rev === body.restoreRevision);
        if (!target) return deny("revision_not_found");
        if (target.rev === L.current) return deny("already_current");
        monitor = { ...target.monitor }; kind = "restore"; restoreOf = target.rev;
      } else {
        const problems = validateMonitor(body?.monitor);
        if (problems.length) return deny("monitor_invalid", { detail: problems.join("; ") });
        monitor = { path: body.monitor.path, receive: body.monitor.receive };
        if (monitor.path === currentOf(L).monitor.path && monitor.receive === currentOf(L).monitor.receive) return deny("no_change");
      }
      const before = evaluate(currentOf(L).monitor);
      const predicted = evaluate(monitor);
      const p = { id: `PLN-${randomBytes(5).toString("hex").toUpperCase()}`, contextId: user.labId, kind, restoreOf, monitor, baseRevision: L.current, fixturesDigest: fixturesDigest(fixtures), predicted, change: compare(before, predicted), planner: user.subject, expiresAt: new Date(now().getTime() + planTtlMs).toISOString(), status: "planned" };
      plans.set(p.id, p);
      await audit.record({ event: "scenario.planned", actor: user.subject, plan: p.id, kind, predicted: predicted.state });
      return { ok: true, plan: planView(p) };
    },

    /** Executes a plan once. A retry, or a concurrent call, returns the first outcome and never adds a second revision. */
    async deploy(user, planId) {
      const p = typeof planId === "string" && PLAN.test(planId) ? plans.get(planId) : undefined;
      if (!p || !visible(user, p)) return deny("not_found");
      if (!can(user.roles, "scenario:run")) return deny("forbidden");
      if (["deployed", "stale", "expired", "failed"].includes(p.status) || p.status === "deploying") return { ok: p.status === "deployed", code: p.status === "deployed" ? undefined : `already_${p.status}`, plan: planView(p), existing: true };
      if (inflight.has(p.id)) return inflight.get(p.id);
      const run = (async () => {
        if (killSwitch()) return deny("kill_switch_engaged", { plan: planView(p) });
        if (now() >= new Date(p.expiresAt)) { p.status = "expired"; return deny("plan_expired", { plan: planView(p) }); }
        const L = lab(p.contextId);
        // Freshness: the lab must still be at the revision the plan was made from, and the fixtures must be what it saw.
        if (L.current !== p.baseRevision || fixturesDigest(fixtures) !== p.fixturesDigest) { p.status = "stale"; await audit.record({ event: "scenario.stale", actor: user.subject, plan: p.id }); return deny("stale_plan_new_plan_required", { plan: planView(p) }); }
        p.status = "deploying";
        const rev = L.revisions.length + 1;
        L.revisions.push({ rev, monitor: p.monitor, source: p.kind === "restore" ? "restore" : "deploy", ...(p.restoreOf ? { restoreOf: p.restoreOf } : {}), poolState: "pending", by: user.name, at: now().toISOString() });
        L.current = rev;
        // Verify: what the fixtures now show must equal what the plan predicted.
        const observed = evaluate(p.monitor);
        const matches = hash(observed) === hash(p.predicted);
        L.revisions.at(-1).poolState = observed.state;
        p.result = { revision: rev, observed, matchedPrediction: matches };
        p.status = matches ? "deployed" : "failed";
        await audit.record({ event: p.kind === "restore" ? "scenario.restored" : "scenario.deployed", actor: user.subject, plan: p.id, revision: rev, outcome: observed.state, matchedPrediction: matches });
        return { ok: matches, ...(matches ? {} : { code: "verification_failed" }), plan: planView(p) };
      })();
      inflight.set(p.id, run);
      try { return await run; } finally { inflight.delete(p.id); }
    },

    getPlan(user, planId) { const p = typeof planId === "string" && PLAN.test(planId) ? plans.get(planId) : undefined; return p && visible(user, p) ? planView(p) : null; }
  };
}
